import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');

// Twenty's own URL builder (twentyhq/twenty e79b3365, packages/twenty-shared/src/utils/image/getLogoUrlFromDomainName.ts,
// its types removed): the address its company avatars put in an <img>
const sanitizeURL = (link) => {
  return link
    ? link.replace(/(https?:\/\/)|(www\.)/g, '').replace(/\/$/, '')
    : '';
};
const getLogoUrlFromDomainName = (domainName) => {
  const sanitizedDomain = sanitizeURL(domainName);
  return sanitizedDomain
    ? `https://twenty-icons.com/${sanitizedDomain}`
    : undefined;
};

// a company Twenty prefills in every new workspace, with its domain as Twenty stores it: its avatar loads the favicon
const url = getLogoUrlFromDomainName('https://www.airbnb.com/');
assert.equal(url, 'https://twenty-icons.com/airbnb.com');
const icon = await fetch(url);
assert.equal(icon.status, 200);
assert.equal(icon.headers.get('content-type'), 'image/png');
const png = new Uint8Array(await icon.arrayBuffer());
assert.deepEqual([...png.slice(0, 8)], [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const width = new DataView(png.buffer).getUint32(16);
assert.equal(width, 192, 'airbnb.com at its largest size');

// a company whose domain the World does not know: the vendor's 404, and Twenty's avatar shows the initial
const unknown = await fetch(getLogoUrlFromDomainName('no-such-company.example'));
assert.equal(unknown.status, 404);
assert.equal(await unknown.text(), 'Could not fetch favicon');
console.log(JSON.stringify({ favicon: url, width, unknown: unknown.status }));
